import csv
from pathlib import Path


def answer() -> int:
    # Przemysław Kurczab is Dawid Majtyka's great-great-grandparent.
    # Of Przemysław's children, these two have more than one grandchild.
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }
    with Path("/app/dataset/people_accounts.csv").open(newline="") as file:
        return sum(
            int(row["account_balance"])
            for row in csv.DictReader(file)
            if (row["first_name"], row["last_name"]) in qualifying_children
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as file:
        json.dump(answer(), file, default=list)
